package com.example.kidhackbackend.users.qrpay.repository;

import com.example.kidhackbackend.users.qrpay.entity.QrPayment;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/**
 * QR 매장결제 조회.
 *
 * <p>⚠️ <b>목록 정렬은 {@code id} 가 아니다(#167).</b> {@code qr_payment.id} 는 V1 에서
 * {@code generated by default as identity} 로 만들어졌다. {@code BY DEFAULT} 는 명시적 id INSERT 를
 * 허용하면서 <b>시퀀스를 따라 올리지 않는다.</b> 그래서 큰 id 로 시드된 행이 있으면 이후 앱이 만드는
 * 결제는 작은 id 를 받아 {@code ORDER BY id DESC} 상위에서 밀려난다. 지갑 원장(#165)·충전 주문과 같은 계열이다.
 *
 * <p><b>결제된 건만 보는 목록은 {@code paidAt} 으로 정렬한다</b> — 화면이 뜻하는 "최신" 이 발급 시각이
 * 아니라 결제 시각이기 때문이다. 발급분까지 포함하는 목록은 {@code createdAt} 을 쓴다.
 *
 * <p>{@code NULLS LAST} 를 명시하는 이유: DESC 정렬의 NULL 위치가 Oracle(NULLS FIRST)과
 * H2(NULLS LAST)에서 반대다. 동일 시각은 {@code id} 로 2차 정렬해 페이징 커서를 안정시킨다.
 */
public interface QrPaymentRepository extends JpaRepository<QrPayment, Long> {

    Optional<QrPayment> findByQrToken(String qrToken);

    /** 발급자(자녀)별 QR 내역 최신순(No.43 폴링에서 재사용) — 발급분 포함이라 createdAt 기준. */
    @Query("SELECT q FROM QrPayment q WHERE q.childId = :childId "
            + "ORDER BY q.createdAt DESC NULLS LAST, q.id DESC")
    List<QrPayment> findByChildIdRecentFirst(@Param("childId") Long childId);

    /** 자녀별 '결제된' 내역(paidAt 존재 = PAID/CANCELLED) 최신순 페이징(No.45) — 결제 시각 기준. */
    @Query("SELECT q FROM QrPayment q WHERE q.childId = :childId AND q.paidAt IS NOT NULL "
            + "ORDER BY q.paidAt DESC NULLS LAST, q.id DESC")
    Page<QrPayment> findByChildIdAndPaidAtIsNotNullRecentFirst(@Param("childId") Long childId,
                                                               Pageable pageable);

    /** 매장 통계용(No.51 MERCHANT): 결제된(paidAt 존재) QR을 기간 필터로. */
    @Query("SELECT q FROM QrPayment q WHERE q.paidAt IS NOT NULL "
            + "AND (:from IS NULL OR q.paidAt >= :from) AND (:to IS NULL OR q.paidAt <= :to)")
    List<QrPayment> findPaidForStats(@Param("from") LocalDateTime from, @Param("to") LocalDateTime to);

    /**
     * 관리자 매장결제 목록(3분할 2/3) — 결제된 QR + 자녀/보호자 + 결제 후 잔액.
     *
     * <p>결제된 건만 대상이라 {@code paid_at IS NOT NULL} 이다(발급만 되고 안 쓴 QR·만료 QR 제외).
     * 자녀는 {@code member}, 보호자는 자녀의 {@code parent_id} 를 한 번 더 조인해 이름까지 내려준다
     * (행마다 회원을 다시 조회하면 N+1).
     *
     * <p>{@code balanceAfter} 는 상관 서브쿼리로 <b>가장 최근 PAYMENT 원장 1건</b>을 고른다 —
     * 같은 qrToken 으로 중복 결제가 가능해({@code [VULN-WALLET-16]}) 단순 조인하면 결제 행이 복제된다.
     * 원래 {@code MAX(t2.id)} 로 골랐는데 이것도 'id 가 크면 최신' 가정이라 시드 데이터에 뒤집힌다(#167).
     * 정렬이 아니라 <b>값을 고르는 자리</b>라, 틀리면 순서가 아니라 {@code balanceAfter} 자체가 틀렸다.
     * {@code ORDER BY created_at ... FETCH FIRST 1 ROW ONLY} 로 바꿨다(Oracle 12c+·H2 모두 지원).
     *
     * <p>LIKE 바인딩 이슈(MemberRepository.searchCustomers 주석)와 서브쿼리 때문에 네이티브로 작성한다.
     */
    @Query(value = "SELECT q.id AS id, q.child_id AS childId, c.username AS childName, "
            + "p.id AS parentId, p.username AS parentName, "
            + "q.store_name AS storeName, q.amount AS amount, q.status AS status, "
            + "(SELECT t.balance_after FROM wallet_transaction t "
            + " WHERE t.ref_uid = q.qr_token AND t.type = 'PAYMENT' "
            + " ORDER BY t.created_at DESC NULLS LAST, t.id DESC "
            + " FETCH FIRST 1 ROW ONLY) AS balanceAfter, "
            + "q.paid_at AS paidAt "
            + "FROM qr_payment q "
            + "LEFT JOIN member c ON c.id = q.child_id "
            + "LEFT JOIN member p ON p.id = c.parent_id "
            + "WHERE q.paid_at IS NOT NULL "
            + "AND (:childId IS NULL OR q.child_id = :childId) "
            + "AND (:status IS NULL OR q.status = :status) "
            + "AND (:merchant IS NULL OR q.store_name LIKE ('%' || :merchant || '%')) "
            + "AND (:keyword IS NULL OR c.username LIKE ('%' || :keyword || '%') "
            + "     OR p.username LIKE ('%' || :keyword || '%')) "
            + "ORDER BY q.paid_at DESC NULLS LAST, q.id DESC",
            countQuery = "SELECT count(*) FROM qr_payment q "
                    + "LEFT JOIN member c ON c.id = q.child_id "
                    + "LEFT JOIN member p ON p.id = c.parent_id "
                    + "WHERE q.paid_at IS NOT NULL "
                    + "AND (:childId IS NULL OR q.child_id = :childId) "
                    + "AND (:status IS NULL OR q.status = :status) "
                    + "AND (:merchant IS NULL OR q.store_name LIKE ('%' || :merchant || '%')) "
                    + "AND (:keyword IS NULL OR c.username LIKE ('%' || :keyword || '%') "
                    + "     OR p.username LIKE ('%' || :keyword || '%'))",
            nativeQuery = true)
    Page<AdminPaymentProjection> adminSearchPayments(@Param("childId") Long childId,
                                                     @Param("status") String status,
                                                     @Param("merchant") String merchant,
                                                     @Param("keyword") String keyword,
                                                     Pageable pageable);
}
